-- Aron's dogs at Easy Beans (business 1), with their photos, each cut square around the dog and made
-- small (480 px JPEGs, as My account → Pets makes them): Fudge and Cooper, which the `pets` migration
-- added without photos, and Pablo and Yoda, new here. Aron is whoever already has Fudge or Cooper there,
-- or else the owner of that name, as in the `pets` migration. A dog that has a photo by now keeps it,
-- and one already there isn't added twice; with no Aron, nothing changes.
do $$
declare
  v_aron uuid;
  d record;
begin
  select p.id into v_aron
    from public.profiles p
   where p.business_id = 1 and p.role in ('admin', 'employee')
     and (p.full_name ~* '^\s*aron\M'
          or exists (select 1 from public.pets x where x.profile_id = p.id and x.name in ('Fudge', 'Cooper')))
   order by exists (select 1 from public.pets x where x.profile_id = p.id and x.name in ('Fudge', 'Cooper')) desc,
            (p.role = 'admin' and p.can_see_pay) desc, p.active desc, p.created_at
   limit 1;
  if v_aron is null then return; end if;
  for d in select * from (values
    ('Fudge', 1, 'data:image/jpeg;base64,'),
    ('Cooper', 2, 'data:image/jpeg;base64,'),
    ('Pablo', 3, 'data:image/jpeg;base64,'),
    ('Yoda', 4, 'data:image/jpeg;base64,')
  ) v(name, sort, photo) loop
    update public.pets set photo = d.photo where profile_id = v_aron and name = d.name and photo is null;
    if not exists (select 1 from public.pets where profile_id = v_aron and name = d.name) then
      insert into public.pets (business_id, profile_id, name, kind, sort, photo) values (1, v_aron, d.name, 'dog', d.sort, d.photo);
    end if;
  end loop;
end $$;
